/**
 * Writes apps/web/src/lib/chain/contracts.generated.ts from the compiled artifacts: the ABIs
 * and creation bytecode of PrizePool and PremiumStore (the owner deploys them from the browser
 * on /admin/chain, so no deploy key ever exists on a server), the HorseMarket ABI (deployed with
 * scripts/deploy-horse-market.ts), plus the EIP-712 EthQuote / SaleOrder / RegistrationOrder /
 * Bid definitions and the pool leaf tag the web app must use.
 *
 *   pnpm --filter @thoroughbred/contracts export:web
 *
 * test/export-web.test.ts fails when the generated file is stale (re-run this after any
 * contract change). The web app gets its own viem; it cannot import this package.
 */
import fs from "node:fs";
import path from "node:path";
import { ethQuoteTypes } from "../adapter/ethQuote";
import { POOL_LEAF_KIND } from "../adapter/prizePool";
import { STORE_EIP712_NAME, STORE_EIP712_VERSION } from "../adapter/voucher";
import { MARKET_EIP712_NAME, MARKET_EIP712_VERSION, bidTypes, registrationOrderTypes, saleOrderTypes } from "../adapter/horseMarket";

export const WEB_CONTRACTS_PATH = path.join(__dirname, "..", "..", "..", "apps", "web", "src", "lib", "chain", "contracts.generated.ts");

function artifact(name: string): { abi: unknown[]; bytecode: string } {
  const file = path.join(__dirname, "..", "artifacts", "contracts", `${name}.sol`, `${name}.json`);
  const a = JSON.parse(fs.readFileSync(file, "utf8")) as { abi: unknown[]; bytecode: string };
  return { abi: a.abi, bytecode: a.bytecode };
}

export function renderWebContracts(): string {
  const pool = artifact("PrizePool");
  const store = artifact("PremiumStore");
  const market = artifact("HorseMarket");
  const j = (v: unknown) => JSON.stringify(v, null, 2);
  return [
    "// GENERATED by packages/contracts/scripts/export-web.ts from the compiled artifacts. Do not edit.",
    "// Re-run `pnpm --filter @thoroughbred/contracts export:web` after any contract change",
    "// (packages/contracts/test/export-web.test.ts fails while this file is stale).",
    "/* eslint-disable */",
    "",
    `export const STORE_EIP712_NAME = ${j(STORE_EIP712_NAME)} as const;`,
    `export const STORE_EIP712_VERSION = ${j(STORE_EIP712_VERSION)} as const;`,
    `export const ethQuoteTypes = ${j(ethQuoteTypes)} as const;`,
    `export const POOL_LEAF_KIND = ${POOL_LEAF_KIND} as const;`,
    `export const MARKET_EIP712_NAME = ${j(MARKET_EIP712_NAME)} as const;`,
    `export const MARKET_EIP712_VERSION = ${j(MARKET_EIP712_VERSION)} as const;`,
    `export const saleOrderTypes = ${j(saleOrderTypes)} as const;`,
    `export const registrationOrderTypes = ${j(registrationOrderTypes)} as const;`,
    `export const bidTypes = ${j(bidTypes)} as const;`,
    "",
    `export const prizePoolAbi = ${j(pool.abi)} as const;`,
    "",
    `export const premiumStoreAbi = ${j(store.abi)} as const;`,
    "",
    `export const horseMarketAbi = ${j(market.abi)} as const;`,
    "",
    `export const prizePoolBytecode = ${j(pool.bytecode)} as \`0x\${string}\`;`,
    "",
    `export const premiumStoreBytecode = ${j(store.bytecode)} as \`0x\${string}\`;`,
    "",
  ].join("\n");
}

if (require.main === module) {
  fs.mkdirSync(path.dirname(WEB_CONTRACTS_PATH), { recursive: true });
  fs.writeFileSync(WEB_CONTRACTS_PATH, renderWebContracts());
  console.log(`wrote ${path.relative(process.cwd(), WEB_CONTRACTS_PATH)}`);
}
